// Different BSPs post different shapes. Normalise, then decide whether
// this message is even something we should act on.

const out = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;

  // Meta Cloud API shape
  const meta = b.entry?.[0]?.changes?.[0]?.value;
  const metaMsg = meta?.messages?.[0];

  const from =
    metaMsg?.from ||
    b.payload?.source ||        // Gupshup
    b.From ||                   // Twilio
    b.sender?.phone ||
    b.from || '';

  const text =
    metaMsg?.text?.body ||
    b.payload?.payload?.text ||
    b.Body ||
    b.text || '';

  const name =
    meta?.contacts?.[0]?.profile?.name ||
    b.payload?.sender?.name ||
    b.ProfileName ||
    b.name || '';

  const type = metaMsg?.type || b.payload?.type || 'text';

  // Status callbacks (delivered / read) come through the same webhook. Ignore them.
  const isStatus = Boolean(meta?.statuses || b.payload?.type === 'message-event' || b.MessageStatus);

  const clean = String(text).trim().slice(0, 1000);
  const phone = String(from).replace(/\D/g, '');

  let skip = '';
  if (isStatus) skip = 'delivery status callback';
  else if (!phone) skip = 'no sender';
  else if (type !== 'text') skip = 'non-text message (' + type + ')';
  else if (!clean) skip = 'empty message';

  const hour = Number(
    new Date().toLocaleString('en-GB', { timeZone: 'Asia/Kolkata', hour: '2-digit', hour12: false })
  );

  out.push({
    json: {
      phone,
      name: String(name).slice(0, 80),
      message: clean,
      type,
      ist_hour: hour,
      received_at: new Date().toISOString(),
      actionable: skip === '',
      skip_reason: skip
    }
  });
}

return out;

