// Default to escalation on any doubt. A human replying late beats a bot
// inventing a price.

const cust = $('Worth Answering?').first().json;
const cfg = $('Config').first().json;
let p = null;

try {
  const raw = $json.content?.[0]?.text || '';
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) p = JSON.parse(m[0]);
} catch (e) { p = null; }

const wantsReply = p?.action === 'reply';
const msg = String(p?.message || '').trim();
const sendable = wantsReply && msg.length > 2 && msg.length <= 900;

// Outside office hours we still reply, but say when a human will follow up.
const open = cust.ist_hour >= cfg.office_open_hour && cust.ist_hour < cfg.office_close_hour;

return [{
  json: {
    ...cust,
    send: sendable,
    reply: sendable
      ? msg + (open ? '' : '\n\nOur team is offline right now — someone will follow up in the morning if you need more.')
      : '',
    escalate: !sendable,
    reason: sendable ? '' : (p?.reason || 'could not produce a safe reply'),
    intent: p?.intent || 'other',
    office_open: open
  }
}];

// One row per conversation turn. Review these weekly — every escalation
// with a repeated intent is a gap you should close in the knowledge base.
const d = $('Decide').first().json;
return [{
  json: {
    at: d.received_at,
    phone: d.phone,
    name: d.name,
    inbound: d.message,
    intent: d.intent,
    handled: d.send ? 'auto' : 'escalated',
    reason: d.reason,
    outbound: d.reply,
    office_hours: d.office_open
  }
}];
